"""Authoring utility: emits reviewable .sdr source. Not part of the HTML build."""
from pathlib import Path
import json
ROOT=Path(__file__).parent
PAGES=[('getting-started','Getting started','Начало работы'),('language-overview','Language overview','Возможности языка'),('text-010','Text values · 0.10','Текст · 0.10'),('records-navigation','Records and navigation','Записи и навигация'),('cli','CLI and builds','CLI и сборка'),('examples','Examples and source','Примеры и исходники'),('release-notes','Release notes','Заметки о выпуске'),('compatibility','Compatibility and storage','Совместимость и хранение'),('roadmap','Roadmap','Дорожная карта'),('web-preview','Experimental Web · 0.11','Экспериментальный Web · 0.11'),('web-platform','Web platform reference','Справочник Web-платформы'),('site-authoring','Native site authoring','Создание нативного сайта'),('project','Project and dedication','Проект и посвящение')]
def q(text):return json.dumps(text,ensure_ascii=False)
def main():
    chrome=[]
    for lang in ('en','ru'):
        prefix='/ru/' if lang=='ru' else '/';name='Russian' if lang=='ru' else 'English'
        chrome += ['component '+name+'Header:', '    navbar label '+q('Навигация' if lang=='ru' else 'Main navigation')+':','        link "Sedrava" to '+q(prefix),'        link '+q('Документация' if lang=='ru' else 'Documentation')+' to '+q(prefix+'getting-started/'),'        link '+q('Примеры' if lang=='ru' else 'Examples')+' to '+q(prefix+'examples/'),'        link "GitHub" to "https://github.com/VasiliiBabkin/sedrava"']
        chrome += ['component '+name+'Footer:','    footer:','        paragraph '+q('Этот сайт написан на Sedrava' if lang=='ru' else 'This website is built with Sedrava'),'        link '+q('Происхождение сборки' if lang=='ru' else 'Build provenance')+' to '+q(prefix+'provenance/'),'        link '+q('Исходный код сайта' if lang=='ru' else 'Website source')+' to "https://github.com/VasiliiBabkin/sedrava-site/blob/feature/sedrava-native-docs-live-examples/sedrava-next/site.sdr"']
        chrome += ['component '+name+'Sidebar:','    sidebar label '+q('Документация' if lang=='ru' else 'Documentation')+':']
        chrome += ['        link '+q(ru if lang=='ru' else en)+' to '+q(prefix+slug+'/') for slug,en,ru in PAGES]
    (ROOT/'components/chrome.sdr').write_text('\n'.join(chrome)+'\n')
    out=['site "Sedrava · native documentation"','origin "https://dev.virtreal.ru"','clean-urls true','robots false','stylesheet "assets/brand.css"','license "assets/INTER_LICENSE.txt"','license "assets/LICENSE_COMPILER.txt"','license "assets/LICENSE_SITE.txt"','favicon "assets/brand/sedrava-logo-32.png"','social-image "assets/brand/sedrava-og.png"','import "components/chrome.sdr"','theme:','    background "#F5F0E8"','    surface "#FFFFFF"','    foreground "#231A35"','    accent "#583C82"','    gold "#8B6419"','    muted "#62596D"','    border "#D6CBDD"']
    for lang in ('en','ru'):
        pre='/ru/' if lang=='ru' else '/';name='Russian' if lang=='ru' else 'English';other='/' if lang=='ru' else '/ru/';locale='English' if lang=='ru' else 'Русский'
        def page(slug,title):
            path=pre+(slug+'/' if slug else '');out.extend(['','page '+lang+'_'+(slug.replace('-','_') or 'home')+' at '+q(path)+':','    title '+q(title+' — Sedrava'),'    description '+q(('Официальная документация Sedrava. Опубликована 0.10.0; возможности этого сайта — экспериментальная 0.11.' if lang=='ru' else 'Official Sedrava documentation. Published language 0.10.0; this native website uses experimental 0.11.')),'    lang '+q(lang),'    use '+name+'Header','    container max 1320 padding 24:','        column gap 24:','            link '+q(locale)+' to '+q(other+(slug+'/' if slug else ''))])
        claim='Этот сайт написан на Sedrava' if lang=='ru' else 'This website is built with Sedrava';page('',claim)
        out+=['            column gap 24 class "hero":','                image "assets/brand/sedrava-logo-512.png" alt '+q('Знак Sedrava: аметистовая складка с золотым разрезом' if lang=='ru' else 'Sedrava folded amethyst ribbon with a gold cut')+' class "hero-image"','                paragraph "SEDRAVA · DESCRIBE → GENERATE" variant eyebrow','                heading '+q(claim),'                paragraph '+q('Опиши приложение — получи приложение. Данные, правила и интерфейс в одном понятном исходнике.' if lang=='ru' else 'Describe the application. Generate the application. Typed data, rules and interface in one readable source.')+' variant lead','                row:','                    button '+q('Начать разработку' if lang=='ru' else 'Start building')+' to '+q(pre+'getting-started/'),'                    button '+q('Запустить примеры' if lang=='ru' else 'Run live examples')+' to '+q(pre+'examples/')+' variant secondary','                paragraph '+q('Опубликована 0.10.0 · Экспериментальный компилятор сайта 0.11' if lang=='ru' else 'Published 0.10.0 · Experimental website compiler 0.11')+' class "brand-label"','            search label '+q('Поиск по документации' if lang=='ru' else 'Search documentation'),'            grid columns 2 class "brand-grid":']
        for demo,en,ru in [('counter','A stateful counter','Счётчик с состоянием'),('tasks','An offline task manager','Офлайн-менеджер задач'),('crm','A related-record client desk','Компании и контакты'),('catalog','A typed HTTP catalog · CI endpoint','HTTP-каталог · сервер CI')]:
            out+=['                card:','                    column:','                        heading '+q(ru if lang=='ru' else en)+' level 2','                        paragraph '+q('Настоящее приложение и точный .sdr-исходник на одной странице.' if lang=='ru' else 'The running application and its exact .sdr source on the same page.'),'                        link '+q('Открыть пример' if lang=='ru' else 'Open example')+' to '+q(pre+'examples/#'+demo)]
        out+=['            markdown '+q('content/'+lang+'/home.md'),'    use '+name+'Footer']
        for index,(slug,en,ru) in enumerate(PAGES):
            title=ru if lang=='ru' else en;page(slug,title)
            out+=['            grid columns 2 class "doc-layout":','                use '+name+'Sidebar','                column gap 24 class "doc-body":','                    heading '+q(title),'                    search label '+q('Поиск по документации' if lang=='ru' else 'Search documentation'),'                    markdown '+q('content/'+lang+'/'+slug+'.md')]
            if slug=='examples':
                out+=['                    callout variant warning:','                        paragraph '+q('Примеры ниже используют экспериментальную 0.11. HTTP-каталог работает с настоящим сервером только в CI; на статическом dev-сайте честно показывает ошибку HTTP, пока endpoint не предоставлен.' if lang=='ru' else 'The live examples below use experimental 0.11. The HTTP catalog uses a real controlled endpoint only in CI; static dev hosting reports an honest HTTP error until an endpoint is provided.')]
                for demo,enlabel,rulabel in [('counter','Counter · persistent state','Счётчик · сохранение состояния'),('tasks','Tasks · CRUD and routes','Задачи · CRUD и переходы'),('crm','CRM · related records and themes','CRM · связанные записи и темы'),('catalog','HTTP catalog · CI-only endpoint','HTTP-каталог · endpoint только в CI')]:out+=['                    demo '+q('demos/'+demo+'.sdr')+' at '+q('/live/'+demo+'/')+' label '+q(rulabel if lang=='ru' else enlabel)+' id '+demo]
            out+=['                    row justify between class "next-prev":']
            previous=PAGES[index-1] if index else None;following=PAGES[index+1] if index+1<len(PAGES) else None
            out+=['                        link '+q('← '+(previous[2] if lang=='ru' else previous[1]) if previous else ('← Главная' if lang=='ru' else '← Home'))+' to '+q(pre+(previous[0]+'/' if previous else ''))]
            if following:out+=['                        link '+q((following[2] if lang=='ru' else following[1])+' →')+' to '+q(pre+following[0]+'/')]
            out+=['    use '+name+'Footer']
        page('provenance','Происхождение сборки' if lang=='ru' else 'Build provenance')
        out+=['            heading '+q('Происхождение сборки' if lang=='ru' else 'Build provenance'),'            markdown "generated/provenance.md"','    use '+name+'Footer']
    (ROOT/'site.sdr').write_text('\n'.join(out)+'\n')
if __name__=='__main__':main()
